CATEGORY_LABELS = {
 "alkali-metal":"Alkali Metal","alkaline-earth":"Alkaline Earth Metal","transition-metal":"Transition Metal",
 "post-transition-metal":"Post-Transition Metal","metalloid":"Metalloid","nonmetal":"Reactive Nonmetal",
 "halogen":"Halogen","noble-gas":"Noble Gas","lanthanide":"Lanthanide","actinide":"Actinide","unknown":"Unknown Properties"
}

STATE_AT_RT = {"H":"gas","He":"gas","N":"gas","O":"gas","F":"gas","Ne":"gas","Cl":"gas","Ar":"gas","Kr":"gas",
"Xe":"gas","Rn":"gas","Og":"gas","Br":"liquid","Hg":"liquid"}

def phase(sym, mp):
    if sym in STATE_AT_RT: return STATE_AT_RT[sym]
    if mp is None: return "solid"
    return "solid" if mp > 298.15 else "liquid"

elements = []
for (z,sym,name,mass,cat,group,period,block,econf,dens,mp,bp,en,ox,disc,year,occ) in ROWS:
    elements.append({
        "atomicNumber": z, "symbol": sym, "name": name, "atomicMass": mass,
        "category": cat, "categoryLabel": CATEGORY_LABELS[cat],
        "group": group, "period": period, "block": block,
        "electronConfiguration": econf,
        "density": dens, "meltingPoint": mp, "boilingPoint": bp,
        "electronegativity": en, "oxidationStates": ox,
        "discoverer": disc, "discoveryYear": year if year else None,
        "naturalOccurrence": occ,
        "stateAtRoomTemp": phase(sym, mp),
        "valency": abs(ox[0]) if ox else 0,
    })

with open("/home/claude/vchem-lab/data/elements.json","w") as f:
    json.dump(elements, f, indent=2)

print("Generated", len(elements), "elements")
